//! Paired directed-edge projection of 509D30 for an explicitly supplied closed mesh.
//! Requires exactly two opposite incidences per edge and every vertex referenced.
use std::{collections::BTreeMap,env,fs,io::{self,Write}};
fn main(){let args:Vec<_>=env::args().collect();assert_eq!(args.len(),2);let b=fs::read(&args[1]).unwrap();assert_eq!(b.len(),1008);let v:Vec<_>=b.chunks_exact(4).map(|x|u32::from_le_bytes(x.try_into().unwrap())).collect();assert!(v.iter().all(|&x|x<44));let mut next=[u32::MAX;252];let mut starts=[u32::MAX;44];let mut edges:BTreeMap<(u32,u32),(usize,u32,u32)>=BTreeMap::new();for base in (0..252).step_by(3){for (from,to) in [(base+2,base),(base,base+1),(base+1,base+2)]{let a=v[from];let c=v[to];assert_ne!(a,c);starts[a as usize]=from as u32;let key=(a.min(c),a.max(c));if let Some(&(other,old_a,old_b))=edges.get(&key){assert_eq!((a,c),(old_b,old_a));assert_eq!(next[other],other as u32);next[other]=from as u32;next[from]=other as u32;}else{next[from]=from as u32;edges.insert(key,(from,a,c));}}}assert!(next.iter().enumerate().all(|(i,&x)|x!=u32::MAX&&x!=i as u32));assert!(starts.iter().all(|&x|x!=u32::MAX));let mut out=Vec::new();out.extend(0u32.to_le_bytes());for n in next{out.extend(n.to_le_bytes())}for n in starts{out.extend(n.to_le_bytes())}io::stdout().write_all(&out).unwrap();}
